// Traditional Branching (Risk of pipeline stall)
int result;
if (condition) {
    result = value_a;
} else {
    result = value_b;
}

// Branchless implementation hint (CMOV)
int result_cmov = condition ? value_a : value_b;
// Modern compilers map this ternary operation to CMOV/SEL instruction.

// Manual Branchless Optimization (Bitwise Masking)
// Example: Find max(a, b) without branching
int diff = a - b;
// Mask based on MSB (1s if negative, 0s if positive)
int mask = diff >> (sizeof(int) * 8 - 1);
int max_val = a - (diff & mask);

